/* MISSION MARS films: where the two mini-films live (files in the normal build, embedded blobs in the one-file build) */
(function(){
"use strict";
var FILES={intro:"assets/video/intro.mp4",finale:"assets/video/finale.mp4"};
var POSTER={"intro": "data:image/webp;base64,", "finale": "data:image/webp;base64,"};
var cache={};
function absolute(p){try{return new URL(p,document.baseURI||location.href).href}catch(e){return p}}
function url(k){
  if(cache[k])return cache[k];
  var B=window.MM_VIDEO_B64;
  if(B&&B[k]){
    try{var bin=atob(B[k]),n=bin.length,u=new Uint8Array(n);for(var i=0;i<n;i++)u[i]=bin.charCodeAt(i);cache[k]=URL.createObjectURL(new Blob([u],{type:"video/mp4"}));return cache[k]}catch(e){}
  }
  return FILES[k]?absolute(FILES[k]):"";
}
window.MMVideo={url:url,poster:function(k){return POSTER[k]||""},has:function(k){return !!(FILES[k]||(window.MM_VIDEO_B64&&window.MM_VIDEO_B64[k]))}};
})();
